INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("ねぇねぇ、騎士クン\n手伝ってあげようよ～", "ヒヨリでっす♪\n元気いっぱいがんばるよ♪", 1, 0, 1, 1001, "お！\nあそこに困ってそうな人発見！", 1, 2, 0, 0, "春咲 ひより", 1.4, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("わ、わたし、\nなに言ってるんだろ\nあはは…", "みんなみたいに\nわたしも強くならなきゃ", 1, 0, 1, 1002, "大切な人を\n守れるようになりたい…って", 1, 2, 0, 0, "草野 優衣", 1.4, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("少しは磨かれると思いますよ。", "フェンシングを始めてみては？", 1, 0, 1, 1003, "キミに必要な集中力と感性が", 1, 2, 0, 0, "士条 怜", 1.4, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("みそぎはねぇ、\nかくれんぼやりたい！", "ねぇ、にいちゃん！", 1, 0, 1, 1004, "今日はなにして遊ぶ？", 1, 2, 0, 0, "穂高 みそぎ", 1.5, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("私といっしょに…\nいかない？", "風宮あかりです", 1, 0, 1, 1006, "ねぇ…", 1, 2, 0, 0, "風宮 あかり", 1.4, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("食べ物の恨みは怖いのー", "出雲宮子なのー", 1, 0, 1, 1007, "プリンたべたいのー", 1, 2, 0, 0, "出雲 宮子", 1.5, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("いいよ。\n見られることは運命さ…", "ボクは虹村雪。", 1, 0, 1, 1008, "キミもボクの美貌に\n吸い寄せられたんだね。", 1, 2, 0, 0, "虹村 雪", 1.4, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("人呼んで「疾風の冥姫」!!", "フッ…聞いて後悔するがいい！", 1, 0, 1, 1009, "我が真名は\nアンネローゼ・フォン・シュテッヒパルム！", 1, 2, 0, 0, "柊杏奈", 1.4, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("ほんまおおきにやわ～♪", "マホマホ王国のプリンセス、\nまほ姫どす", 1, 0, 1, 1010, "うさぎさん、\n運命の王子はんに巡りあわせてくれて", 1, 2, 0, 0, "姫宮 真歩", 1.5, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("ここで会ったが\n100年目～！", "衣之咲璃乃です！", 1, 0, 1, 1011, "生き別れたお兄ちゃんを探して\n三千世界！", 1, 2, 0, 0, "衣之咲 璃乃", 1.4, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("…って、お願い！\n誰にも言わないでおいて～！", "私はハツネ、\n結構強いんだよ。\nきらーん☆", 1, 0, 1, 1012, "ち、超能力って…\n何のことかな～？", 1, 2, 0, 0, "柏崎 初音", 1.4, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("ヒデサイまぢ\nGF（グッドフィーリング）～♪", "ちょす！\n美波鈴奈だよ～♪", 1, 0, 1, 1016, "一応カリスマ読モJKやってまっす！", 1, 2, 0, 0, "美波 鈴奈", 1.4, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("でも、沖縄もとってもいいとこさー", "はいたーい。\n喜屋武香織さー。", 1, 0, 1, 1017, "東京は遊園地みたいなところさー", 1, 2, 0, 0, "喜屋武 香織", 1.4, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("イオちゃんって呼んでね。", "支倉伊緒です。", 1, 0, 1, 1018, "先生って呼ばれるのは\nくすぐったいから", 1, 2, 0, 0, "支倉 伊緒", 1.4, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("ミミをおいてかないでぇ～", "ふえ…？\nミミ、むずかしいこと\nよくわかんない…", 1, 0, 1, 1020, "あ！/\お兄ちゃ～ん\nまってよ～", 1, 2, 0, 0, "茜 ミミ", 1.5, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("ふぇぇぇぇぇん……", "あ…あの…えっと…\n栗…林…くるみ…です……", 1, 0, 1, 1021, "あの……\nふぇ……", 1, 2, 0, 0, "栗林 くるみ", 1.5, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("なんてありがとうございます！", "風宮よりです。\nあああああ！", 1, 0, 1, 1022, "こんな私に貴重な時間を\n割いていただき、", 1, 2, 0, 0, "風宮 より", 1.4, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("私こっち行きたいー\nね、早く早くー", "私、アヤネ！\nぷうきちと一緒についてってあげるね！", 1, 0, 1, 1023, "おにいちゃんどこいくの？\nえ？", 1, 2, 0, 0, "北条 綾音", 1.5, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("これて何か違う…\nあああすみません！", "わっ…わっ…私、\n天野すずめといいます！", 1, 0, 1, 1025, "ふ、不束者ですが\nどうぞ末永く…って、", 1, 2, 0, 0, "天野 すずめ", 1.4, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("離しませんわ………\n絶対に…!!", "……クスクス…私は\n…倉石恵理子……", 1, 0, 1, 1027, "あなたは…運命の……\n伴侶……", 1, 2, 0, 0, "倉石 恵理子", 1.4, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("…そうでしょ？？", "佐々木咲恋よ。\nねえ、世の中に無駄なことが\n多すぎると思わない？", 1, 0, 1, 1028, "その無駄を省くことができれば、\nもっと余裕のある暮らしができるっ！", 1, 2, 0, 0, "佐々木 咲恋", 1.4, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("あはは、\n私もまだまだだなぁ～", "桜井望だよ！\nよろしくねっ", 1, 0, 1, 1029, "ぇっと…\nキミ、私のこと知らないの?!", 1, 2, 0, 0, "桜井 望", 1.4, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("ショーグン、\nワタシと一緒に天下統一デース！", "デケデケデンっ！", 1, 0, 1, 1030, "初めまして、\n私はニノン・ジュベール申すデス！", 1, 2, 0, 0, "ニノン・ジュベール", 1.4, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("おかしいですね……", "上喜しのぶです。\n手元のドクロが父です。", 1, 0, 1, 1031, "でもって私の隣にいるのが……\nえ、見えない？", 1, 2, 0, 0, "上喜 しのぶ", 1.4, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("そう、\nオラのボケに突っ込める相方が…！", "目指すはビッグな\nお笑い芸人だっぺ！", 1, 0, 1, 1033, "けんども\nそれには足りないモンが…", 1, 2, 0, 0, "野戸まひる", 1.5, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("ちょ\nちょっと一杯飲んできます…！", "あの…私…綾瀬ゆかりです…\nあの…ごめんなさい！", 1, 0, 1, 1034, "ちょっと緊張しちゃって…", 1, 2, 0, 0, "綾瀬 ゆかり", 1.4, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("これ以上お話しすることは…\nないです！", "氷川鏡華…です", 1, 0, 1, 1036, "知らない人とは話しちゃいけないので", 1, 2, 0, 0, "氷川 鏡華", 1.5, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("私体が弱いから、\n30分に一度休憩しないと\nいけないんです。", "柏崎…栞です。", 1, 0, 1, 1038, "……あ、アラーム。", 1, 2, 0, 0, "柏崎 栞", 1.4, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("野に咲く花が、\n唯一の話相手です。", "ふ、双葉碧です。", 1, 0, 1, 1040, "私、一人も友達がいなくて……", 1, 2, 0, 0, "双葉 碧", 1.4, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("そう思っています。", "三角千歌です。", 1, 0, 1, 1042, "私の歌声で、\n皆さんが幸せになってくれたらいいなって…", 1, 2, 0, 0, "三角 千歌", 1.4, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("う、疑ってすまなかったな…", "安芸真琴だ。", 1, 0, 1, 1043, "あぁ？\nお前のそいつの仲間か？", 1, 2, 0, 0, "安芸 真琴", 1.4, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("わらわの偉大な力に\nひれ伏すがいい！\nはっはっは！", "わらわこそは夜を総べる者！", 1, 0, 1, 1044, "生けとし生ける全ての者よ！", 1, 2, 0, 0, "イリヤ・オーンスタイン", 1.4, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("ｌク、クウカに何かご用ですか!?", "そこで騎士は妖精を乱暴に……", 1, 0, 1, 1045, "ぐふふふふ……はっ！", 1, 2, 0, 0, "遠見 空花", 1.4, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("う～ん…\n猫ってホントに最高にゃ～♪", "宮坂たまきにゃ♪\n猫はいいにゃよ？", 1, 0, 1, 1046, "自由気ままで♪\n寝て遊んで、食べてケンカして…", 1, 2, 0, 0, "宮坂たまき", 1.4, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("…と思ったら\nバイトの時間だ！\nまたあとでね！", "大神美冬よ！", 1, 0, 1, 1048, "それでは早速クエストに…", 1, 2, 0, 0, "大神 美冬", 1.4, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("お姉ちゃんがぜ～んぶ\nやってあげるからね！", "星野静流だよ！", 1, 0, 1, 1049, "クエストもバトルも\n掃除も洗濯も", 1, 2, 0, 0, "星野静流", 1.4, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("学校では誰もが憧れる\nアイドル的な存在ってやつよ♪", "アタシは玉泉美咲。", 1, 0, 1, 1050, "見ての通りの\nセクシー美少女で", 1, 2, 0, 0, "玉泉美咲", 1.5, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("？？？？", "？？？", 1, 0, 1, 1052, "？？？？", 1, 2, 0, 0, "リマ", 1.4, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("そ、そこまでいうなら\nもらってやる", "モニカ・ヴァイスヴィントだ。", 1, 0, 1, 1053, "菓子でつろうなどと\n稚拙な策を……", 1, 2, 0, 0, "モニカ・ヴァイスヴィント", 1.5, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("そ、そこまでいうなら\nもらってやる", "モニカ・ヴァイスヴィントだ。", 1, 0, 1, 1058, "菓子でつろうなどと\n稚拙な策を……", 1, 2, 0, 0, "ペコリーヌ", 1.5, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("そ、そこまでいうなら\nもらってやる", "モニカ・ヴァイスヴィントだ。", 1, 0, 1, 1059, "菓子でつろうなどと\n稚拙な策を……", 1, 2, 0, 0, "コッコロ", 1.5, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("そ、そこまでいうなら\nもらってやる", "モニカ・ヴァイスヴィントだ。", 1, 0, 1, 1060, "菓子でつろうなどと\n稚拙な策を……", 1, 2, 0, 0, "キャル", 1.5, 0, 0);
